mapper.insert:
INSERT INTO mq_message_log (
    message_id, topic, routing_key, message_body, status,
    retry_count, max_retry, next_retry_time, create_time, update_time
) VALUES (
    #{messageId}, #{topic}, #{routingKey}, #{messageBody}, #{status},
    #{retryCount}, #{maxRetry}, #{nextRetryTime}, #{createTime}, #{updateTime}
)

mapper.select:
SELECT 
FROM mq_message_log
WHERE status IN (0, -1)
  AND next_retry_time <= #{beforeTime}
  AND retry_count < #{maxRetry}
ORDER BY create_time ASC
